userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;margin-bottom:2px;">NaCl cubic unit cell</div>
<div style="font-size:11px;line-height:1.35;color:#333;margin-bottom:4px;">Hover an ion to see its coordinate relative to the origin.</div>
<label style="gap:4px;">
  <span>Emphasis</span>
  <div style="display:flex;gap:5px;flex-wrap:wrap;">
    <button id="modeIon" class="active" type="button">Ion colors</button>
    <button id="modeLabels" type="button">Mass labels</button>
  </div>
</label>
<div style="height:1px;background:#ddd;margin:4px 0;"></div>
<div style="font-weight:700;">Demo steps</div>
<button id="step0" type="button">1. Crystal pattern</button>
<button id="step1" type="button">2. Center-of-mass bookkeeping</button>
<div id="stepNarration" style="font-size:11px;line-height:1.35;color:#333;margin-top:3px;">
  The cube corners alternate red and green so that every edge connects unlike-colored ions.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// cube edge → Line dashed orange #ff6a21 connecting adjacent corner ions
// x axis    → Line black #111111 plus ConeGeometry arrowhead, label x
// y axis    → Line black #111111 plus ConeGeometry arrowhead, label y
// z axis    → Line black #111111 plus ConeGeometry arrowhead, label z
// ions      → SphereGeometry(0.21) glossy Phong red/green at eight cube corners
// highlights→ small SphereGeometry glossy yellow-green/orange-red spots on ions
// hover glow→ transparent SphereGeometry shell around hovered ion
// labels    → HTML labels 0, x, y, z, and italic m with numeric subscripts

const a = 2;
const redBase = new THREE.Color(0xc7302b);
const greenBase = new THREE.Color(0x6f9d2f);
const redMuted = new THREE.Color(0xc87370);
const greenMuted = new THREE.Color(0x93a66b);
const orangeEdge = 0xff6a21;

function W(x, y, z) {
  return new THREE.Vector3(x, z, -y);
}

scene.add(new THREE.AmbientLight(0xffffff, 0.48));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.15);
keyLight.position.set(-3.5, 5.2, 4.5);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xfff1df, 0.42);
fillLight.position.set(4, 2, -3);
scene.add(fillLight);

const cubeCorners = {
  m1: { tex: [0, 0, 0], species: 'green', label: 'm<sub>1</sub>', coord: '(0,0,0)' },
  m2: { tex: [a, 0, 0], species: 'red', label: 'm<sub>2</sub>', coord: '(a,0,0)' },
  m3: { tex: [a, a, 0], species: 'green', label: 'm<sub>3</sub>', coord: '(a,a,0)' },
  m4: { tex: [0, a, 0], species: 'red', label: 'm<sub>4</sub>', coord: '(0,a,0)' },
  m5: { tex: [0, 0, a], species: 'red', label: 'm<sub>5</sub>', coord: '(0,0,a)' },
  m6: { tex: [a, 0, a], species: 'green', label: 'm<sub>6</sub>', coord: '(a,0,a)' },
  m7: { tex: [a, a, a], species: 'red', label: 'm<sub>7</sub>', coord: '(a,a,a)' },
  m8: { tex: [0, a, a], species: 'green', label: 'm<sub>8</sub>', coord: '(0,a,a)' }
};

for (const key in cubeCorners) {
  const c = cubeCorners[key];
  c.world = W(c.tex[0], c.tex[1], c.tex[2]);
}

const edgeMat = new THREE.LineDashedMaterial({
  color: orangeEdge,
  dashSize: 0.13,
  gapSize: 0.075,
  linewidth: 1.4
});

function dashedEdge(p, q) {
  const geom = new THREE.BufferGeometry().setFromPoints([p, q]);
  const line = new THREE.Line(geom, edgeMat);
  line.computeLineDistances();
  scene.add(line);
  return line;
}

const cornerNames = Object.keys(cubeCorners);
for (let i = 0; i < cornerNames.length; i++) {
  for (let j = i + 1; j < cornerNames.length; j++) {
    const ci = cubeCorners[cornerNames[i]].tex;
    const cj = cubeCorners[cornerNames[j]].tex;
    const diff = (ci[0] !== cj[0]) + (ci[1] !== cj[1]) + (ci[2] !== cj[2]);
    const dist = Math.abs(ci[0] - cj[0]) + Math.abs(ci[1] - cj[1]) + Math.abs(ci[2] - cj[2]);
    if (diff === 1 && Math.abs(dist - a) < 1e-6) {
      dashedEdge(cubeCorners[cornerNames[i]].world, cubeCorners[cornerNames[j]].world);
    }
  }
}

const axisMat = new THREE.LineBasicMaterial({ color: 0x111111 });
function axisArrow(start, end) {
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([start, end]),
    axisMat
  );
  scene.add(line);

  const dir = end.clone().sub(start).normalize();
  const h = 0.18;
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.055, h, 24),
    new THREE.MeshBasicMaterial({ color: 0x111111 })
  );
  cone.position.copy(end).addScaledVector(dir, -h / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(cone);
  return { line, cone };
}

axisArrow(W(0, 0, 0), W(2.8, 0, 0));
axisArrow(W(0, 0, 0), W(0, 2.8, 0));
axisArrow(W(0, 0, 0), W(0, 0, 2.7));

const sphereGeom = new THREE.SphereGeometry(0.21, 48, 32);
const highlightGeom = new THREE.SphereGeometry(0.045, 24, 16);
const ionObjects = [];

for (const name of cornerNames) {
  const data = cubeCorners[name];
  const isGreen = data.species === 'green';
  const mat = new THREE.MeshPhongMaterial({
    color: isGreen ? greenBase : redBase,
    specular: 0xffffff,
    shininess: 68
  });
  const mesh = new THREE.Mesh(sphereGeom, mat);
  mesh.position.copy(data.world);
  mesh.userData.cornerName = name;
  mesh.userData.species = data.species;
  mesh.userData.coord = data.coord;
  scene.add(mesh);

  const hMat = new THREE.MeshBasicMaterial({
    color: isGreen ? 0xc5da54 : 0xff745f,
    transparent: true,
    opacity: 0.78,
    depthWrite: false
  });
  const highlight = new THREE.Mesh(highlightGeom, hMat);
  highlight.position.copy(data.world).add(new THREE.Vector3(-0.07, 0.105, 0.105));
  scene.add(highlight);

  registerInteractive(mesh, {
    title: data.label.replace('<sub>', '').replace('</sub>', ''),
    tooltip: `${name}: ${data.coord} — ${data.species} ion`,
    body: `${data.label} is the ${data.species} corner ion at coordinate ${data.coord} relative to the origin.`
  });

  ionObjects.push({ name, data, mesh, highlight, baseMaterial: mat, highlightMaterial: hMat });
}

const glow = new THREE.Mesh(
  new THREE.SphereGeometry(0.265, 48, 24),
  new THREE.MeshBasicMaterial({
    color: 0xffd64a,
    transparent: true,
    opacity: 0.28,
    wireframe: true,
    depthWrite: false
  })
);
glow.visible = false;
scene.add(glow);

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.72
});

const axisLabels = [
  addLabel('<i>x</i>', W(3.0, 0, 0), { fontSize: '15px', bold: true, offset: [6, 7] }),
  addLabel('<i>y</i>', W(0, 3.0, 0), { fontSize: '15px', bold: true, offset: [6, -2] }),
  addLabel('<i>z</i>', W(0, 0, 2.9), { fontSize: '15px', bold: true, offset: [-2, -10] }),
  addLabel('0', W(0, 0, 0), { fontSize: '16px', offset: [-38, 17] })
];

const massOffsets = {
  m1: [-5, 27],
  m2: [15, 27],
  m3: [28, 2],
  m4: [20, -12],
  m5: [-31, 0],
  m6: [28, 9],
  m7: [24, -16],
  m8: [-14, -25]
};

const massLabels = {};
for (const name of cornerNames) {
  const entry = addLabel(`<i>m</i><sub>${name.slice(1)}</sub>`, cubeCorners[name].world, {
    fontSize: '14px',
    color: '#111',
    offset: massOffsets[name]
  });
  massLabels[name] = entry;
}

let displayMode = 'Ion colors';
let hoveredName = null;

function setButtonState() {
  document.getElementById('modeIon').classList.toggle('active', displayMode === 'Ion colors');
  document.getElementById('modeLabels').classList.toggle('active', displayMode === 'Mass labels');
}

function setMassLabelMode() {
  const massMode = displayMode === 'Mass labels';
  for (const name of cornerNames) {
    const div = massLabels[name].div;
    div.style.fontSize = massMode ? '17px' : '13px';
    div.style.fontWeight = massMode ? '700' : '400';
    div.style.opacity = massMode ? '1' : '0.68';
    div.style.background = massMode ? 'rgba(255,255,255,0.82)' : 'transparent';
    div.style.padding = massMode ? '1px 5px' : '0';
    div.style.borderRadius = massMode ? '4px' : '0';
  }
}

function updateIonAppearance() {
  const massMode = displayMode === 'Mass labels';
  for (const item of ionObjects) {
    const sameSpecies = hoveredName && item.data.species === cubeCorners[hoveredName].species;
    const isHovered = hoveredName === item.name;
    const base = item.data.species === 'green'
      ? (massMode ? greenMuted : greenBase)
      : (massMode ? redMuted : redBase);

    item.mesh.material.color.copy(base);
    item.mesh.material.emissive = item.mesh.material.emissive || new THREE.Color(0x000000);
    item.mesh.material.emissive.set(sameSpecies ? (item.data.species === 'green' ? 0x223300 : 0x330000) : 0x000000);
    item.mesh.material.shininess = massMode ? 38 : 68;
    item.mesh.scale.setScalar(isHovered ? 1.22 : 1.0);

    item.highlight.visible = !massMode || isHovered || sameSpecies;
    item.highlight.material.opacity = isHovered ? 0.95 : (massMode ? 0.38 : 0.78);
  }

  if (hoveredName) {
    glow.visible = true;
    glow.position.copy(cubeCorners[hoveredName].world);
  } else {
    glow.visible = false;
  }
}

function applyDisplayMode(mode) {
  displayMode = mode;
  setButtonState();
  setMassLabelMode();
  updateIonAppearance();
}

document.getElementById('modeIon').addEventListener('click', () => applyDisplayMode('Ion colors'));
document.getElementById('modeLabels').addEventListener('click', () => applyDisplayMode('Mass labels'));

const hoverRay = new THREE.Raycaster();
const hoverPointer = new THREE.Vector2();

function hitIon(event) {
  const rect = canvas.getBoundingClientRect();
  hoverPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  hoverPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  hoverRay.setFromCamera(hoverPointer, camera);
  const hits = hoverRay.intersectObjects(ionObjects.map(o => o.mesh), false);
  return hits.length ? hits[0].object.userData.cornerName : null;
}

canvas.addEventListener('pointermove', (event) => {
  const hitName = hitIon(event);
  if (hitName !== hoveredName) {
    hoveredName = hitName;
    updateIonAppearance();
  }
  if (hitName) {
    const d0 = cubeCorners[hitName];
    showTooltip(`${hitName}: ${d0.coord} — ${d0.species} ion`, event);
  }
});

canvas.addEventListener('pointerleave', () => {
  hoveredName = null;
  updateIonAppearance();
  hideTooltip();
});

const steps = [
  {
    title: 'Crystal pattern',
    narration: 'The cube corners alternate red and green so that every edge connects unlike-colored ions. This makes the sodium-chloride-like checkerboard pattern visible before focusing on the calculation.',
    state: { displayMode: 'Ion colors' }
  },
  {
    title: 'Center-of-mass bookkeeping',
    narration: 'Switching emphasis to labels makes m1 through m8 and their corner coordinates the main information. Hovering any sphere reveals its coordinate triplet relative to the origin corner.',
    state: { displayMode: 'Mass labels' }
  }
];

function goToStep(index) {
  const step = steps[Math.max(0, Math.min(steps.length - 1, index | 0))];
  applyDisplayMode(step.state.displayMode);
  document.getElementById('stepNarration').textContent = step.narration;
  document.getElementById('step0').classList.toggle('active', step === steps[0]);
  document.getElementById('step1').classList.toggle('active', step === steps[1]);
  showPopup(step.title, step.narration);
}

window.goToStep = goToStep;
document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));

applyDisplayMode('Ion colors');
document.getElementById('step0').classList.add('active');
// @FIGURE_CODE_END

