const mainLight = new THREE.DirectionalLight(0xffffff, 1.18);
mainLight.position.set(-3.5, 4.8, 4.2);
scene.add(mainLight);
const rimLight = new THREE.DirectionalLight(0xffecd5, 0.35);
rimLight.position.set(3.5, 2.2, -3.6);
scene.add(rimLight);

const corners = {
  m1: { c: [0, 0, 0], color: 'green', label: '<i>m</i><sub>1</sub>', coord: '(0, 0, 0)' },
  m2: { c: [side, 0, 0], color: 'red', label: '<i>m</i><sub>2</sub>', coord: '(a, 0, 0)' },
  m3: { c: [side, side, 0], color: 'green', label: '<i>m</i><sub>3</sub>', coord: '(a, a, 0)' },
  m4: { c: [0, side, 0], color: 'red', label: '<i>m</i><sub>4</sub>', coord: '(0, a, 0)' },
  m5: { c: [0, 0, side], color: 'red', label: '<i>m</i><sub>5</sub>', coord: '(0, 0, a)' },
  m6: { c: [side, 0, side], color: 'green', label: '<i>m</i><sub>6</sub>', coord: '(a, 0, a)' },
  m7: { c: [side, side, side], color: 'red', label: '<i>m</i><sub>7</sub>', coord: '(a, a, a)' },
  m8: { c: [0, side, side], color: 'green', label: '<i>m</i><sub>8</sub>', coord: '(0, a, a)' }
};

for (const name of Object.keys(corners)) {
  const q = corners[name].c;
  corners[name].p = P(q[0], q[1], q[2]);
}

const edgeGroup = new THREE.Group();
scene.add(edgeGroup);
const dashedMat = new THREE.LineDashedMaterial({
  color: edgeColor,
  dashSize: 0.075,
  gapSize: 0.055,
  transparent: true,
  opacity: 0.96
});

function makeDashedEdge(a, b) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const l = new THREE.Line(g, dashedMat);
  l.computeLineDistances();
  edgeGroup.add(l);
  return l;
}

const names = Object.keys(corners);
for (let i = 0; i < names.length; i++) {
  for (let j = i + 1; j < names.length; j++) {
    const A = corners[names[i]].c;
    const B = corners[names[j]].c;
    const changed = (A[0] !== B[0]) + (A[1] !== B[1]) + (A[2] !== B[2]);
    const manhattan = Math.abs(A[0] - B[0]) + Math.abs(A[1] - B[1]) + Math.abs(A[2] - B[2]);
    if (changed === 1 && Math.abs(manhattan - side) < 1e-8) {
      makeDashedEdge(corners[names[i]].p, corners[names[j]].p);
    }
  }
}

const axisMat = new THREE.LineBasicMaterial({ color: 0x111111, depthTest: false });
const arrowMat = new THREE.MeshBasicMaterial({ color: 0x111111, side: THREE.DoubleSide, depthTest: false });

function axisLine(start, end) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([start, end]), axisMat);
  line.renderOrder = 5;
  scene.add(line);
  return line;
}

function flatArrowHead(tip, screenDir, depthZ, size = 0.16, width = 0.08) {
  const dir = new THREE.Vector2(screenDir[0], screenDir[1]).normalize();
  const perp = new THREE.Vector2(-dir.y, dir.x);
  const base = new THREE.Vector2(tip.x, tip.y).addScaledVector(dir, -size);
  const v1 = new THREE.Vector3(tip.x, tip.y, depthZ);
  const v2 = new THREE.Vector3(base.x + perp.x * width, base.y + perp.y * width, depthZ);
  const v3 = new THREE.Vector3(base.x - perp.x * width, base.y - perp.y * width, depthZ);
  const geom = new THREE.BufferGeometry().setFromPoints([v1, v2, v3]);
  geom.setIndex([0, 1, 2]);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, arrowMat);
  mesh.renderOrder = 6;
  scene.add(mesh);
  return mesh;
}

const origin = P(0, 0, 0);
const xTip = P(side * 1.48, 0, 0);
const yTip = P(0, side * 1.47, 0);
const zTip = P(0, 0, side * 1.45);
axisLine(origin, xTip);
axisLine(origin, yTip);
axisLine(origin, zTip);
flatArrowHead(xTip, [1, 0], xTip.z);
flatArrowHead(yTip, [1, 1], yTip.z);
flatArrowHead(zTip, [0, 1], zTip.z);

const massGeom = new THREE.SphereGeometry(0.17, 48, 32);
const glintGeom = new THREE.SphereGeometry(0.034, 20, 12);
const massObjects = [];

for (const name of names) {
  const data = corners[name];
  const isGreen = data.color === 'green';
  const mat = new THREE.MeshPhongMaterial({
    color: isGreen ? greenColor : redColor,
    specular: 0xffffff,
    shininess: 72
  });
  const mass = new THREE.Mesh(massGeom, mat);
  mass.position.copy(data.p);
  mass.userData.massName = name;
  mass.userData.coord = data.coord;
  scene.add(mass);

  const glint = new THREE.Mesh(
    glintGeom,
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.86, depthWrite: false })
  );
  glint.position.copy(data.p).add(new THREE.Vector3(-0.055, 0.075, 0.095));
  glint.renderOrder = 4;
  scene.add(glint);

  registerInteractive(mass, {
    title: data.label,
    tooltip: `${name}: coordinate ${data.coord}`,
    body: `${data.label} is the corner mass at coordinate ${data.coord}. The cube side length is denoted by a.`
  });

  massObjects.push({ name, data, mesh: mass, glint, material: mat });
}

const halo = new THREE.Mesh(
  new THREE.SphereGeometry(0.215, 42, 20),
  new THREE.MeshBasicMaterial({
    color: 0xffd34e,
    transparent: true,
    opacity: 0.38,
    wireframe: true,
    depthWrite: false
  })
);
halo.visible = false;
halo.renderOrder = 7;
scene.add(halo);

setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: 45,
  depthScale: depthOblique,
  heightFraction: 0.78,
  target: [1.14, 1.08, -0.77],
  distanceScale: 1.12
});

addLabel('0', P(0, 0, 0), { fontSize: '16px', offset: [-36, 17] });
addLabel('<i>x</i>', P(side * 1.58, 0, 0), { fontSize: '15px', bold: true, offset: [8, 12] });
addLabel('<i>y</i>', P(0, side * 1.56, 0), { fontSize: '15px', bold: true, offset: [13, -5] });
addLabel('<i>z</i>', P(0, 0, side * 1.55), { fontSize: '15px', bold: true, offset: [-5, -13] });

const massOffsets = {
  m1: [-2, 28],
  m2: [0, 29],
  m3: [32, 2],
  m4: [30, -8],
  m5: [-33, 0],
  m6: [31, 12],
  m7: [18, -20],
  m8: [-2, -24]
};

const massLabels = {};
for (const name of names) {
  massLabels[name] = addLabel(corners[name].label, corners[name].p, {
    fontSize: '14px',
    color: '#111',
    offset: massOffsets[name]
  });
}

let mode = 'labels';
let hoverName = null;
let sizeScale = 1;

function refreshButtons() {
  document.getElementById('modeLabels').classList.toggle('active', mode === 'labels');
  document.getElementById('modeColors').classList.toggle('active', mode === 'colors');
}

function updateAppearance() {
  const labelMode = mode === 'labels';
  for (const item of massObjects) {
    const isHovered = hoverName === item.name;
    const sameColor = hoverName && item.data.color === corners[hoverName].color;
    const base = item.data.color === 'green' ? greenColor : redColor;
    const soft = item.data.color === 'green' ? greenSoft : redSoft;

    item.mesh.material.color.copy(labelMode ? base : base);
    item.mesh.material.emissive = item.mesh.material.emissive || new THREE.Color(0x000000);
    item.mesh.material.emissive.set(isHovered ? 0x332200 : (sameColor && mode === 'colors' ? 0x151500 : 0x000000));
    item.mesh.material.shininess = labelMode ? 72 : 88;
    item.mesh.scale.setScalar(sizeScale * (isHovered ? 1.16 : 1));
    item.glint.visible = true;
    item.glint.scale.setScalar(sizeScale * (isHovered ? 1.1 : 1));

    const div = massLabels[item.name].div;
    div.style.opacity = labelMode ? '1' : '0.72';
    div.style.fontWeight = labelMode ? '700' : '400';
    div.style.fontSize = labelMode ? '15px' : '13px';
    div.style.background = labelMode ? 'rgba(255,255,255,0.72)' : 'transparent';
    div.style.padding = labelMode ? '1px 4px' : '0';
    div.style.borderRadius = labelMode ? '4px' : '0';
  }

  if (hoverName) {
    halo.visible = true;
    halo.position.copy(corners[hoverName].p);
    halo.scale.setScalar(sizeScale);
  } else {
    halo.visible = false;
  }
  refreshButtons();
}

function setMode(next) {
  mode = next;
  updateAppearance();
}

document.getElementById('modeLabels').addEventListener('click', () => setMode('labels'));
document.getElementById('modeColors').addEventListener('click', () => setMode('colors'));

document.getElementById('sphereSize').addEventListener('input', (event) => {
  sizeScale = Number(event.target.value) / 100;
  updateAppearance();
});

document.getElementById('toggleEdges').addEventListener('change', (event) => {
  edgeGroup.visible = event.target.checked;
});

const localRaycaster = new THREE.Raycaster();
const localPointer = new THREE.Vector2();

function massHit(event) {
  const rect = canvas.getBoundingClientRect();
  localPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  localPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  localRaycaster.setFromCamera(localPointer, camera);
  const hits = localRaycaster.intersectObjects(massObjects.map(o => o.mesh), false);
  return hits.length ? hits[0].object.userData.massName : null;
}

canvas.addEventListener('pointermove', (event) => {
  const hit = massHit(event);
  if (hit !== hoverName) {
    hoverName = hit;
    updateAppearance();
  }
  if (hit) showTooltip(`${hit}: coordinate ${corners[hit].coord}`, event);
});

canvas.addEventListener('pointerleave', () => {
  hoverName = null;
  updateAppearance();
  hideTooltip();
});

const steps = [
  {
    mode: 'labels',
    text: 'The default view matches the mass-labelled cube: x runs right, y runs up-right, and z is vertical.',
    popupTitle: 'Original mass diagram'
  },
  {
    mode: 'colors',
    text: 'Hover any corner to connect its mass label with its coordinate triplet. The red/green coloring is only a visual aid for separating neighboring corners.',
    popupTitle: 'Corner coordinates'
  }
];

function goStep(i) {
  const index = Math.max(0, Math.min(steps.length - 1, i | 0));
  const step = steps[index];
  setMode(step.mode);
  document.getElementById('stepNarration').textContent = step.text;
  document.getElementById('step0').classList.toggle('active', index === 0);
  document.getElementById('step1').classList.toggle('active', index === 1);
  showPopup(step.popupTitle, step.text);
}

document.getElementById('step0').addEventListener('click', () => goStep(0));
document.getElementById('step1').addEventListener('click', () => goStep(1));

updateAppearance();
